using System;
using System.Collections.Generic;

class CrudSimulado {
    // Simulamos una tabla de BD en memoria
    private List<Dictionary<string, object>> tabla = new List<Dictionary<string, object>>();
    private int nextId = 1;

    // CREATE
    public void Insertar(string nombre, int edad) {
        var registro = new Dictionary<string, object> {
            { "Id", nextId++ },
            { "Nombre", nombre },
            { "Edad", edad }
        };
        tabla.Add(registro);
        Console.WriteLine($"✅ Insertado: {nombre} (Edad: {edad})");
    }

    // READ
    public void Listar() {
        Console.WriteLine("\n📋 Lista de Estudiantes:");
        foreach (var fila in tabla) {
            Console.WriteLine($"  ID: {fila["Id"]} | Nombre: {fila["Nombre"]} | Edad: {fila["Edad"]}");
        }
    }

    // UPDATE
    public void Actualizar(int id, string nuevoNombre) {
        foreach (var fila in tabla) {
            if ((int)fila["Id"] == id) {
                fila["Nombre"] = nuevoNombre;
                Console.WriteLine($"✏️ Actualizado ID {id} a: {nuevoNombre}");
                return;
            }
        }
        Console.WriteLine($"❌ No se encontró el ID {id}");
    }

    // DELETE
    public void Eliminar(int id) {
        tabla.RemoveAll(f => (int)f["Id"] == id);
        Console.WriteLine($"🗑️ Eliminado registro con ID {id}");
    }
}

class Main {
    static void Main() {
        var crud = new CrudSimulado();

        // 1. Inserta estudiantes iniciales
        crud.Insertar("Ana Torres", 21);
        crud.Insertar("Luis Gómez", 23);

        // 2. TODO: Inserta a 'Pedro Ramírez' de 20 años aquí


        // 3. Lista todos los estudiantes
        crud.Listar();
    }
}

